//! Pinned Go strconv.IsPrint Unicode data for Go string quoting.
//!
//! Source: go1.26.0 src/strconv/isprint.go (identical in go1.26.9).
//! Source SHA-256: 24114557c2b3cad7b80c8e71683831bfbe1c72eb99e8fd28a3a48eaf77705fb4
//! Generated from Go's range endpoints and excluded code points. Kept private
//! so output does not change with the Rust toolchain's Unicode version.

pub(super) fn printable(ch: char) -> bool {
    let code = u32::from(ch);
    let index = RANGES.partition_point(|&(_, end)| end < code);
    RANGES.get(index).is_some_and(|&(start, _)| start <= code)
        && EXCLUDED.binary_search(&code).is_err()
}

